package main

import (
	"gno.land/r/gov/dao"
	validators "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	pr := validators.NewValidatorProposalRequest(cross(cur),
		[]validators.ValoperChange{validators.NewValoperChange(address("g1ps3yvz3fjkmpng8p5jaysjd92uh73z5s6trv59"), 0)},
		"Eject validator samourai-crew-4 (g1g646r47fzalv5wde6fcfh2x856zeas358z4ewd) from the valset [fixture 1]",
		"Automated ejection proposal generated by katana (e2e fixture capture).\nScore: 12/100 over current_week",
	)
	dao.MustCreateProposal(cross(cur), pr)
}

